1	// Screenshot helper: node scripts/shot.mjs <url> <width> <out.png> [height]
2	// Uses playwright-core with the locally installed Chromium headless shell.
3	import { chromium } from 'playwright-core';
4	
5	const [url, width = '1280', out = 'shot.png', height = '800'] = process.argv.slice(2);
6	if (!url) { console.error('usage: node scripts/shot.mjs <url> <width> <out.png> [height]'); process.exit(2); }
7	const browser = await chromium.launch();
8	const page = await browser.newPage({ viewport: { width: Number(width), height: Number(height) } });
9	await page.goto(url);
10	await page.screenshot({ path: out, fullPage: true });
11	await browser.close();
12	console.log(`wrote ${out} (${width}x${height})`);
