import("playwright-core").then(async ({ chromium }) => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1024, height: 900 } });
  await page.goto("http://127.0.0.1:4173/");

  // Click + on keyboard line 11 times to try to exceed MAX_QTY=10
  for (let i = 0; i < 11; i++) {
    await page.click("#lines .line:nth-child(1) .inc");
  }
  const afterInc = await page.$eval("#lines .line:nth-child(1) .qty", el => el.textContent);
  const incDisabled = await page.$eval("#lines .line:nth-child(1) .inc", el => el.disabled);
  console.log("qty after 11 clicks of +:", afterInc, "inc disabled:", incDisabled);

  // Now click - many times to try to go below MIN_QTY=1
  for (let i = 0; i < 15; i++) {
    await page.click("#lines .line:nth-child(1) .dec");
  }
  const afterDec = await page.$eval("#lines .line:nth-child(1) .qty", el => el.textContent);
  const decDisabled = await page.$eval("#lines .line:nth-child(1) .dec", el => el.disabled);
  console.log("qty after 15 clicks of -:", afterDec, "dec disabled:", decDisabled);

  await browser.close();
});
'

