import("playwright-core").then(async ({ chromium }) => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1024, height: 900 } });
  await page.goto("http://127.0.0.1:4173/");
  await page.click("#lines .line:nth-child(1) .inc");
  await page.click("#lines .line:nth-child(1) .inc");
  const before = await page.$eval("#lines .line:nth-child(1) .qty", el => el.textContent);
  await page.reload();
  const after = await page.$eval("#lines .line:nth-child(1) .qty", el => el.textContent);
  console.log("qty before reload:", before, "qty after reload:", after);

  // remove all lines, check empty state
  for (let i = 0; i < 3; i++) {
    await page.click("#lines .line:nth-child(1) .remove");
  }
  const emptyHidden = await page.$eval("#empty", el => el.hidden);
  const summaryHidden = await page.$eval("#summary", el => el.classList.contains("is-hidden"));
  console.log("empty shown:", !emptyHidden, "summary hidden:", summaryHidden);
  await browser.close();
});
'
